WITH parsed AS (SELECT id, service, host, log_ts, latency_ms, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, CAST((status_code & 1) != 0 AS INT) AS is_flagged FROM app_logs) SELECT CASE WHEN is_flagged >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_flagged_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, host, MIN(log_ts) AS first_seen, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, SIZE(COLLECT_SET(host)) AS num_hosts, ROUND(SUM(is_flagged) / NULLIF(COUNT(CASE WHEN service = 'checkout' THEN 1 END), 0), 2) AS is_flagged_per_checkout, BIT_OR(latency_ms) AS latency_ms_bit_or FROM parsed GROUP BY 1, 2, 3 ORDER BY is_flagged_per_checkout DESC NULLS LAST
